from collections import Counter

def transform(grid):
    h, n = len(grid), len(grid[0])

    # The separator is a solid vertical line near the center.
    solid = [
        c for c in range(n)
        if all(grid[r][c] == grid[0][c] for r in range(h))
    ]
    div = min(solid, key=lambda c: abs(c - (n - 1) / 2))

    left = [row[:div] for row in grid]
    right = [row[div + 1:] for row in grid]
    w = min(len(left[0]), len(right[0]))

    def sparse_color(panel):
        counts = Counter(v for row in panel for v in row)
        return min(counts, key=counts.get)

    left_obj = sparse_color(left)
    right_obj = sparse_color(right)

    out = [[right_obj] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if left[r][c] == left_obj and right[r][c] == right_obj:
                out[r][c] = 3
    return out
