def transform(grid):
    h, w = len(grid), len(grid[0])

    # Locate the solid separator and split into the two panels.
    vertical = [
        c for c in range(w)
        if all(grid[r][c] == grid[0][c] for r in range(h))
    ]
    horizontal = [
        r for r in range(h)
        if all(v == grid[r][0] for v in grid[r])
    ]

    if vertical:
        c = min(vertical, key=lambda x: abs(x - (w - 1) / 2))
        a = [row[:c] for row in grid]
        b = [row[c + 1:] for row in grid]
    else:
        r = min(horizontal, key=lambda x: abs(x - (h - 1) / 2))
        a = grid[:r]
        b = grid[r + 1:]

    common = set(v for row in a for v in row) & set(v for row in b for v in row)
    color = min(common) if common else 0

    out_h = min(len(a), len(b))
    out_w = min(len(a[0]), len(b[0]))
    out = [[color] * out_w for _ in range(out_h)]
    for i in range(out_h):
        for j in range(out_w):
            if a[i][j] == color and b[i][j] == color:
                out[i][j] = 3
    return out
